import { describe, it, expect } from "vitest";
import {
  applyOps,
  buildRequest,
  canonical,
  emptyMeta,
  isDirty,
  snapshotOf,
  type ConnectStorage,
  type LocalProfile,
  type ServerProfile,
} from "../../../../packages/mt-ui/src/connectSync";
import { WEB_PROFILES } from "../../../../packages/mt-ui/src/__fixtures__/connectWebProfiles";
import { normalizeData, upsertLocal } from "../profiles";

// Profiles built in the console's web editor must load in BACnet Explorer exactly as written. The fixtures are
// generated by the console's own schema; this pushes them through the app's parser, its Connect storage
// (the upsert useConnectSync runs) and the sync bookkeeping.
const bacnet = WEB_PROFILES.filter((p) => p.app === "bacnet-explorer");

/** The hook's storage, over an in-memory list instead of localStorage. */
function appStorage() {
  let list: LocalProfile[] = [];
  const storage: ConnectStorage = {
    list: () => list,
    upsert: ({ key, name, data }) => {
      list = upsertLocal(list, key, name, data);
      return name;
    },
    remove: (key) => {
      list = list.filter((p) => p.key !== key);
    },
  };
  return storage;
}

const served = (p: (typeof bacnet)[number], version = 1): ServerProfile => ({
  id: `web-${p.name}`,
  app: "bacnet-explorer",
  name: p.name,
  team_id: null,
  data: p.data,
  version,
  seq: 1,
  deleted: false,
  can_edit: true,
  updated_at: 1,
});

/** Header and rows of the console's watch-list CSV, read the way a spreadsheet would (quoted cells). */
function cells(csv: string): string[][] {
  return csv
    .trim()
    .split("\n")
    .slice(1)
    .map((line) => [...line.matchAll(/"((?:[^"]|"")*)"|([^,]+)/g)].map((m) => (m[1] ?? m[2] ?? "").replace(/""/g, '"')));
}

describe("web-edited BACnet Explorer profiles", () => {
  it("has fixtures to run (guards against an empty generated file)", () => {
    expect(bacnet.length).toBeGreaterThanOrEqual(2);
  });

  for (const p of bacnet) {
    describe(p.name, () => {
      it("loads without losing or inventing anything", () => {
        expect(canonical(normalizeData(p.data))).toBe(canonical(p.data));
      });

      it("keeps every watched object (the app drops entries it can not use)", () => {
        const watch = p.data.watch as unknown[];
        expect(normalizeData(p.data).watch).toHaveLength(watch.length);
      });

      it("downloads through sync as a clean profile: not marked changed, nothing to upload back", () => {
        const storage = appStorage();
        const res = applyOps([{ op: "added", profile: served(p) }], [], storage, emptyMeta(), 1, "s", 0);
        const local = storage.list()[0] as LocalProfile;
        expect(local.name).toBe(p.name);
        expect(isDirty(res.meta, local)).toBe(false);
        expect(res.meta.links[local.key]?.snapshot).toBe(snapshotOf(p.name, p.data, null));
        expect(buildRequest(storage.list(), res.meta, [], false).locals.every((l) => !l.dirty)).toBe(true);
      });

      it("replaces an older local copy with the web edit and stays clean", () => {
        const storage = appStorage();
        const first = applyOps([{ op: "added", profile: served(p, 1) }], [], storage, emptyMeta(), 1, "s", 0);
        const edited = { ...p.data, device: { ...(p.data.device as object), port: 47810 } };
        const res = applyOps(
          [{ op: "pulled", key: p.name, profile: { ...served(p, 2), data: edited } }],
          [],
          storage,
          first.meta,
          2,
          "s",
          0,
        );
        const local = storage.list()[0] as LocalProfile;
        expect(canonical(local.data)).toBe(canonical(edited));
        expect(isDirty(res.meta, local)).toBe(false);
      });

      it("exports one CSV row per watched object", () => {
        const watch = normalizeData(p.data).watch;
        expect(cells(p.csv)).toEqual(watch.map((w) => [w.type, String(w.instance), w.name, w.source]));
      });
    });
  }
});
